USE HealthCarePortalDB;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetAll AS SELECT d.*,s.SpecializationName,dep.DepartmentName FROM dbo.Doctors d JOIN dbo.Specializations s ON s.SpecializationId=d.SpecializationId JOIN dbo.Departments dep ON dep.DepartmentId=s.DepartmentId WHERE d.IsActive=1 ORDER BY d.FirstName;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetById @DoctorId INT AS SELECT d.*,s.SpecializationName,dep.DepartmentName,dep.DepartmentId FROM dbo.Doctors d JOIN dbo.Specializations s ON s.SpecializationId=d.SpecializationId JOIN dbo.Departments dep ON dep.DepartmentId=s.DepartmentId WHERE d.DoctorId=@DoctorId;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_Search @Search NVARCHAR(200)=NULL,@DepartmentId INT=NULL,@SpecializationId INT=NULL AS SELECT d.*,s.SpecializationName,dep.DepartmentName FROM dbo.Doctors d JOIN dbo.Specializations s ON s.SpecializationId=d.SpecializationId JOIN dbo.Departments dep ON dep.DepartmentId=s.DepartmentId WHERE d.IsActive=1 AND (@Search IS NULL OR d.FirstName LIKE N'%'+@Search+N'%' OR d.LastName LIKE N'%'+@Search+N'%') AND (@DepartmentId IS NULL OR dep.DepartmentId=@DepartmentId) AND (@SpecializationId IS NULL OR d.SpecializationId=@SpecializationId);
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetDashboard @DoctorId INT AS SELECT @DoctorId DoctorId,(SELECT COUNT(*) FROM dbo.Appointments WHERE DoctorId=@DoctorId AND AppointmentDate=CONVERT(date,GETDATE())) TodayAppointments,(SELECT COUNT(*) FROM dbo.Appointments WHERE DoctorId=@DoctorId AND AppointmentStatus=N'Completed') CompletedAppointments,(SELECT COUNT(*) FROM dbo.Patients p JOIN dbo.Appointments a ON a.PatientId=p.PatientId WHERE a.DoctorId=@DoctorId) PatientVisits;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetSchedule @DoctorId INT AS SELECT * FROM dbo.DoctorSchedules WHERE DoctorId=@DoctorId AND IsActive=1 ORDER BY DayOfWeek,StartTime;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_SaveSchedule @ScheduleId INT=NULL,@DoctorId INT,@DayOfWeek TINYINT,@StartTime TIME,@EndTime TIME,@BreakStartTime TIME=NULL,@BreakEndTime TIME=NULL,@SlotDurationMinutes INT=30 AS
BEGIN SET NOCOUNT ON; IF @EndTime<=@StartTime OR @SlotDurationMinutes<=0 THROW 50003,N'Invalid schedule times or slot duration.',1; IF @ScheduleId IS NULL INSERT dbo.DoctorSchedules(DoctorId,DayOfWeek,StartTime,EndTime,BreakStartTime,BreakEndTime,SlotDurationMinutes) VALUES(@DoctorId,@DayOfWeek,@StartTime,@EndTime,@BreakStartTime,@BreakEndTime,@SlotDurationMinutes); ELSE UPDATE dbo.DoctorSchedules SET DoctorId=@DoctorId,DayOfWeek=@DayOfWeek,StartTime=@StartTime,EndTime=@EndTime,BreakStartTime=@BreakStartTime,BreakEndTime=@BreakEndTime,SlotDurationMinutes=@SlotDurationMinutes WHERE ScheduleId=@ScheduleId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetAppointments @DoctorId INT,@FromDate DATE=NULL,@ToDate DATE=NULL AS SELECT a.*,p.PatientCode,p.FirstName PatientFirstName,p.LastName PatientLastName,p.Phone PatientPhone,dep.DepartmentName FROM dbo.Appointments a JOIN dbo.Patients p ON p.PatientId=a.PatientId JOIN dbo.Departments dep ON dep.DepartmentId=a.DepartmentId WHERE a.DoctorId=@DoctorId AND (@FromDate IS NULL OR a.AppointmentDate>=@FromDate) AND (@ToDate IS NULL OR a.AppointmentDate<=@ToDate) ORDER BY a.AppointmentDate,a.StartTime;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetPatients @DoctorId INT AS SELECT DISTINCT p.* FROM dbo.Patients p JOIN dbo.Appointments a ON a.PatientId=p.PatientId WHERE a.DoctorId=@DoctorId;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_GetPatientMedicalHistory @DoctorId INT,@PatientId INT AS SELECT mr.* FROM dbo.MedicalRecords mr WHERE mr.DoctorId=@DoctorId AND mr.PatientId=@PatientId ORDER BY mr.RecordDate DESC;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_Create @UserId INT=NULL,@DoctorCode NVARCHAR(30),@FirstName NVARCHAR(100),@LastName NVARCHAR(100)=NULL,@Gender NVARCHAR(20),@DateOfBirth DATE=NULL,@Phone NVARCHAR(20),@Email NVARCHAR(150),@Qualification NVARCHAR(250)=NULL,@SpecializationId INT,@ExperienceYears INT=0,@ConsultationFee DECIMAL(10,2),@AboutDoctor NVARCHAR(2000)=NULL AS BEGIN SET NOCOUNT ON; INSERT dbo.Doctors(UserId,DoctorCode,FirstName,LastName,Gender,DateOfBirth,Phone,Email,Qualification,SpecializationId,ExperienceYears,ConsultationFee,AboutDoctor) VALUES(@UserId,@DoctorCode,@FirstName,@LastName,@Gender,@DateOfBirth,@Phone,@Email,@Qualification,@SpecializationId,@ExperienceYears,@ConsultationFee,@AboutDoctor); SELECT CONVERT(INT, SCOPE_IDENTITY()) DoctorId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_Update @DoctorId INT,@FirstName NVARCHAR(100),@LastName NVARCHAR(100)=NULL,@Gender NVARCHAR(20)=NULL,@Phone NVARCHAR(20),@Email NVARCHAR(150),@Qualification NVARCHAR(250)=NULL,@SpecializationId INT,@ExperienceYears INT,@ConsultationFee DECIMAL(10,2),@AboutDoctor NVARCHAR(2000)=NULL AS BEGIN SET NOCOUNT ON; UPDATE dbo.Doctors SET FirstName=@FirstName,LastName=@LastName,Gender=COALESCE(@Gender, Gender),Phone=@Phone,Email=@Email,Qualification=COALESCE(@Qualification, Qualification),SpecializationId=@SpecializationId,ExperienceYears=@ExperienceYears,ConsultationFee=@ConsultationFee,AboutDoctor=@AboutDoctor,UpdatedAt=SYSDATETIME() WHERE DoctorId=@DoctorId; IF @@ROWCOUNT=0 THROW 50004,N'Doctor not found.',1; UPDATE u SET u.Email = @Email, u.UpdatedAt = SYSDATETIME() FROM dbo.Users u JOIN dbo.Doctors d ON d.UserId = u.UserId WHERE d.DoctorId = @DoctorId AND u.Email <> @Email; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_Deactivate @DoctorId INT AS BEGIN SET NOCOUNT ON; UPDATE dbo.Doctors SET IsActive=0,UpdatedAt=SYSDATETIME() WHERE DoctorId=@DoctorId; UPDATE u SET u.IsActive=0, u.UpdatedAt=SYSDATETIME() FROM dbo.Users u JOIN dbo.Doctors d ON d.UserId=u.UserId WHERE d.DoctorId=@DoctorId; IF @@ROWCOUNT=0 THROW 50004,N'Doctor not found.',1; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Doctor_Activate @DoctorId INT AS BEGIN SET NOCOUNT ON; UPDATE dbo.Doctors SET IsActive=1,UpdatedAt=SYSDATETIME() WHERE DoctorId=@DoctorId; UPDATE u SET u.IsActive=1, u.UpdatedAt=SYSDATETIME() FROM dbo.Users u JOIN dbo.Doctors d ON d.UserId=u.UserId WHERE d.DoctorId=@DoctorId; IF @@ROWCOUNT=0 THROW 50004,N'Doctor not found.',1; END;
GO
